-- 来自 GitHub 固定提交的 Rust current 构造器完整执行结果；保留历史表结构。
CREATE TABLE locator_observations ( id TEXT PRIMARY KEY, locator_id TEXT NOT NULL REFERENCES contact_locators(id) ON DELETE RESTRICT, source_id TEXT NOT NULL REFERENCES observation_sources(id) ON DELETE RESTRICT, creator_id TEXT REFERENCES creators(id) ON DELETE RESTRICT, platform_account_id TEXT REFERENCES platform_accounts(id) ON DELETE RESTRICT, observed_value TEXT NOT NULL, observed_at INTEGER NOT NULL, CHECK(creator_id IS NOT NULL OR platform_account_id IS NOT NULL) );
CREATE TABLE locator_resolutions ( id TEXT PRIMARY KEY, locator_id TEXT NOT NULL REFERENCES contact_locators(id) ON DELETE RESTRICT, account_ref_id TEXT NOT NULL REFERENCES account_refs(id) ON DELETE RESTRICT, resolved_target_id TEXT NOT NULL REFERENCES resolved_targets(id) ON DELETE RESTRICT, state TEXT NOT NULL CHECK(state IN ('active','invalidated')), resolved_at INTEGER NOT NULL, invalidated_at INTEGER );
CREATE TABLE mailbox_credential_deletion_guards ( mailbox_ref_id TEXT PRIMARY KEY REFERENCES mailbox_refs(id) ON DELETE CASCADE, created_at INTEGER NOT NULL );
CREATE TABLE mailbox_identity_mappings ( mailbox_ref_id TEXT PRIMARY KEY REFERENCES mailbox_refs(id) ON DELETE RESTRICT, auth_connection_id TEXT NOT NULL, provider_kind TEXT NOT NULL CHECK(provider_kind IN ('resend','smtp','imap','remote')), projection_kind TEXT NOT NULL CHECK(projection_kind IN ('mailbox','send_as')), capability_projection_revision INTEGER NOT NULL CHECK(capability_projection_revision >= 1), checkpoint_namespace TEXT NOT NULL CHECK(length(trim(checkpoint_namespace)) BETWEEN 1 AND 256), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, FOREIGN KEY(auth_connection_id, provider_kind) REFERENCES email_auth_connections(id, provider_kind) ON DELETE RESTRICT );
CREATE TABLE mailbox_refs ( id TEXT PRIMARY KEY, provider TEXT NOT NULL CHECK(provider IN ('resend','smtp','imap','gmail')), label TEXT NOT NULL, email_address TEXT NOT NULL, display_name TEXT, capabilities_json TEXT NOT NULL, available INTEGER NOT NULL, last_error TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL );
CREATE TABLE mailbox_sync_incremental_continuations ( mailbox_ref_id TEXT NOT NULL, direction TEXT NOT NULL CHECK(direction IN ('inbound','outbound')), next_cursor TEXT NOT NULL CHECK(length(trim( next_cursor, char(9) || char(10) || char(11) || char(12) || char(13) || ' ' )) > 0), newest_provider_message_id TEXT NOT NULL CHECK(length(trim( newest_provider_message_id, char(9) || char(10) || char(11) || char(12) || char(13) || ' ' )) > 0), newest_occurred_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, PRIMARY KEY(mailbox_ref_id, direction), FOREIGN KEY(mailbox_ref_id, direction) REFERENCES mailbox_sync_state(mailbox_ref_id, direction) ON DELETE CASCADE );
CREATE TABLE mailbox_sync_state ( mailbox_ref_id TEXT NOT NULL REFERENCES mailbox_refs(id) ON DELETE CASCADE, direction TEXT NOT NULL CHECK(direction IN ('inbound','outbound')), newest_provider_message_id TEXT, newest_occurred_at INTEGER, oldest_backfill_cursor TEXT, backfill_complete INTEGER NOT NULL CHECK(backfill_complete IN (0,1)), last_page_at INTEGER, last_full_sync_at INTEGER, failure_json TEXT CHECK(failure_json IS NULL OR (json_valid(failure_json) AND json_type(failure_json) = 'object')), updated_at INTEGER NOT NULL, PRIMARY KEY(mailbox_ref_id, direction) );
CREATE TABLE messages ( id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE RESTRICT, external_message_id TEXT, sender_target_id TEXT REFERENCES resolved_targets(id) ON DELETE RESTRICT, direction TEXT NOT NULL, body TEXT NOT NULL, status TEXT NOT NULL, public_json TEXT NOT NULL DEFAULT '{}', sent_at INTEGER NOT NULL, UNIQUE(conversation_id, external_message_id) );
CREATE TABLE observation_sources ( id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ( 'initial_platform_account','profile_bio','profile_website','profile_location', 'video_description','channel_description','link_hub','manual_business_email', 'community_administrator','manual_entry','contact_route_resolution', 'creator_import' )), platform TEXT CHECK(platform IS NULL OR platform IN ('x','instagram','telegram','youtube','tiktok')), source_url TEXT, external_ref TEXT, account_ref_id TEXT REFERENCES account_refs(id) ON DELETE RESTRICT, metadata_json TEXT NOT NULL DEFAULT '{}', observed_at INTEGER NOT NULL );
CREATE TABLE platform_account_observations ( id TEXT PRIMARY KEY, platform_account_id TEXT NOT NULL REFERENCES platform_accounts(id) ON DELETE RESTRICT, source_id TEXT NOT NULL REFERENCES observation_sources(id) ON DELETE RESTRICT, handle TEXT, display_name TEXT, profile_url TEXT, public_json TEXT NOT NULL DEFAULT '{}', observed_at INTEGER NOT NULL );
CREATE TABLE platform_accounts ( id TEXT PRIMARY KEY, platform TEXT NOT NULL CHECK(platform IN ('x','instagram','telegram','youtube','tiktok')), target_kind TEXT NOT NULL CHECK(target_kind IN ('user','bot','channel','supergroup','group','creator','business')), external_id TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(platform, target_kind, external_id) );
CREATE TABLE reply_triage ( id TEXT PRIMARY KEY, channel TEXT NOT NULL CHECK(channel IN ('email','dm')), email_id TEXT REFERENCES emails(id) ON DELETE CASCADE, message_id TEXT REFERENCES messages(id) ON DELETE CASCADE, intent TEXT NOT NULL CHECK(intent IN ('interested','question','negotiating','declined','irrelevant','other')), summary TEXT NOT NULL, suggested_reply TEXT, created_at INTEGER NOT NULL, acknowledged_at INTEGER, CHECK((channel = 'email' AND email_id IS NOT NULL AND message_id IS NULL) OR (channel = 'dm' AND message_id IS NOT NULL AND email_id IS NULL)) );
CREATE TABLE resolved_targets ( id TEXT PRIMARY KEY, account_ref_id TEXT NOT NULL REFERENCES account_refs(id) ON DELETE RESTRICT, platform TEXT NOT NULL CHECK(platform IN ('x','instagram','telegram','youtube','tiktok')), target_kind TEXT NOT NULL CHECK(target_kind IN ('user','bot','channel','supergroup','group','creator','business')), external_target_id TEXT NOT NULL, platform_account_id TEXT REFERENCES platform_accounts(id) ON DELETE RESTRICT, metadata_json TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(account_ref_id, platform, target_kind, external_target_id) );
CREATE TABLE touchpoints ( id TEXT PRIMARY KEY, creator_id TEXT NOT NULL REFERENCES creators(id) ON DELETE RESTRICT, contact_route_id TEXT REFERENCES creator_contact_routes(id) ON DELETE RESTRICT, kind TEXT NOT NULL, message_id TEXT REFERENCES messages(id) ON DELETE RESTRICT, email_id TEXT REFERENCES emails(id) ON DELETE RESTRICT, account_relationship_id TEXT REFERENCES account_relationships(id) ON DELETE RESTRICT, occurred_at INTEGER NOT NULL, metadata_json TEXT NOT NULL DEFAULT '{}' );
CREATE TABLE discovery_search_positions ( position INTEGER PRIMARY KEY, search_hit_id TEXT NOT NULL UNIQUE REFERENCES discovery_search_hits(id) ON DELETE CASCADE );
CREATE TABLE discovery_target_increases ( id TEXT PRIMARY KEY NOT NULL CHECK(length(id) BETWEEN 1 AND 128), operator_account_id TEXT NOT NULL CHECK(length(trim(operator_account_id)) BETWEEN 1 AND 256), discovery_campaign_id TEXT NOT NULL REFERENCES discovery_campaigns(id) ON DELETE CASCADE, criteria_revision INTEGER NOT NULL CHECK(criteria_revision >= 1), previous_target_count INTEGER NOT NULL CHECK(previous_target_count BETWEEN 1 AND 10000), new_target_count INTEGER NOT NULL CHECK(new_target_count BETWEEN 1 AND 10000 AND new_target_count != previous_target_count), used_calls_at_decision INTEGER NOT NULL CHECK(used_calls_at_decision >= 0), created_at INTEGER NOT NULL CHECK(created_at >= 0), FOREIGN KEY(discovery_campaign_id, criteria_revision) REFERENCES discovery_campaign_revisions(discovery_campaign_id, revision) ON DELETE CASCADE );
CREATE TABLE discovery_transcript_reads ( search_hit_id TEXT PRIMARY KEY REFERENCES discovery_search_hits(id) ON DELETE CASCADE, candidate_id TEXT NOT NULL REFERENCES discovery_candidates(id) ON DELETE CASCADE, call_number INTEGER NOT NULL CHECK(call_number > 0), status TEXT NOT NULL CHECK(status IN ('reading','completed','unavailable','failed')), segments_json TEXT NOT NULL CHECK(json_valid(segments_json) AND length(CAST(segments_json AS BLOB)) <= 24000), truncated INTEGER NOT NULL CHECK(truncated IN (0,1)), stop_code TEXT, updated_at INTEGER NOT NULL );
CREATE TABLE discovery_video_completions ( search_hit_id TEXT PRIMARY KEY REFERENCES discovery_search_hits(id) ON DELETE CASCADE, completed_at INTEGER NOT NULL );
CREATE TABLE discovery_video_identity_bindings ( search_hit_id TEXT PRIMARY KEY REFERENCES discovery_video_completions(search_hit_id) ON DELETE CASCADE, discovery_campaign_id TEXT NOT NULL, criteria_revision INTEGER NOT NULL CHECK(criteria_revision >= 1), candidate_id TEXT NOT NULL REFERENCES discovery_candidates(id) ON DELETE CASCADE, native_author_id TEXT NOT NULL CHECK(length(native_author_id) BETWEEN 1 AND 256), created_at INTEGER NOT NULL, FOREIGN KEY(discovery_campaign_id, criteria_revision) REFERENCES discovery_campaign_revisions(discovery_campaign_id, revision) ON DELETE CASCADE );
CREATE TABLE discovery_video_read_failures ( search_hit_id TEXT PRIMARY KEY REFERENCES discovery_search_hits(id) ON DELETE CASCADE, call_number INTEGER NOT NULL CHECK(call_number > 0), stop_code TEXT NOT NULL CHECK(length(stop_code) BETWEEN 1 AND 128), updated_at INTEGER NOT NULL );
CREATE TABLE discovery_web_source_reads ( search_hit_id TEXT PRIMARY KEY NOT NULL REFERENCES discovery_search_hits(id) ON DELETE CASCADE, discovery_campaign_id TEXT NOT NULL REFERENCES discovery_campaigns(id) ON DELETE CASCADE, origin_platform TEXT NOT NULL CHECK(origin_platform IN ('google','yahoo')), profile_ref TEXT NOT NULL CHECK(length(profile_ref) BETWEEN 1 AND 256), source_url TEXT NOT NULL CHECK(length(source_url) BETWEEN 1 AND 2048), expected_revision INTEGER NOT NULL CHECK(expected_revision >= 1), call_number INTEGER NOT NULL CHECK(call_number > 0), target_platform TEXT NOT NULL CHECK(target_platform IN ('youtube','twitter','douyin')), video_id TEXT NOT NULL CHECK((target_platform='youtube' AND length(video_id)=11 AND video_id NOT GLOB '*[^a-zA-Z0-9_-]*') OR (target_platform IN ('twitter','douyin') AND length(video_id) BETWEEN 1 AND 20 AND substr(video_id,1,1)!='0' AND video_id NOT GLOB '*[^0-9]*')), status TEXT NOT NULL CHECK(status IN ('reading','completed','failed')), native_author_id TEXT, native_material_json TEXT, stop_code TEXT, updated_at INTEGER NOT NULL CHECK(updated_at >= 0), FOREIGN KEY(discovery_campaign_id,origin_platform,profile_ref) REFERENCES discovery_platform_runs(discovery_campaign_id,platform,profile_ref) ON DELETE CASCADE, FOREIGN KEY(discovery_campaign_id,expected_revision) REFERENCES discovery_campaign_revisions(discovery_campaign_id,revision) ON DELETE CASCADE, CHECK((status='reading' AND native_author_id IS NULL AND native_material_json IS NULL AND stop_code IS NULL) OR (status='completed' AND target_platform='youtube' AND native_author_id IS NOT NULL AND length(native_author_id)=24 AND substr(native_author_id,1,2)='UC' AND native_author_id NOT GLOB '*[^a-zA-Z0-9_-]*' AND native_material_json IS NOT NULL AND json_valid(native_material_json) AND json_type(native_material_json)='object' AND length(CAST(native_material_json AS BLOB))<=65536 AND json_extract(native_material_json,'$.channelId') IS native_author_id AND json_extract(native_material_json,'$.videoId') IS video_id AND stop_code IS NULL) OR (status='completed' AND target_platform='twitter' AND native_author_id IS NOT NULL AND length(native_author_id) BETWEEN 1 AND 20 AND substr(native_author_id,1,1)!='0' AND native_author_id NOT GLOB '*[^0-9]*' AND native_material_json IS NOT NULL AND json_valid(native_material_json) AND json_type(native_material_json)='object' AND length(CAST(native_material_json AS BLOB))<=65536 AND json_extract(native_material_json,'$.identity.account_id') IS native_author_id AND json_extract(native_material_json,'$.identity.post_id') IS video_id AND json_extract(native_material_json,'$.identity.source_url') IS lower(source_url) AND json_extract(native_material_json,'$.profile.account_id') IS native_author_id AND json_extract(native_material_json,'$.content.identity') IS json_extract(native_material_json,'$.identity') AND stop_code IS NULL) OR (status='completed' AND target_platform='douyin' AND native_author_id IS NOT NULL AND length(native_author_id) BETWEEN 19 AND 99 AND substr(native_author_id,1,12)='MS4wLjABAAAA' AND native_author_id NOT GLOB '*[^a-zA-Z0-9_-]*' AND native_material_json IS NOT NULL AND json_valid(native_material_json) AND json_type(native_material_json)='object' AND length(CAST(native_material_json AS BLOB))<=65536 AND json_extract(native_material_json,'$.content.author_id') IS native_author_id AND json_extract(native_material_json,'$.profile.author_id') IS native_author_id AND json_extract(native_material_json,'$.content.post_id') IS video_id AND json_extract(native_material_json,'$.content.source_url') IS source_url AND json_extract(native_material_json,'$.profile.profile_url') IS ('https://www.douyin.com/user/' || native_author_id) AND json_extract(native_material_json,'$.content.profile_url') IS json_extract(native_material_json,'$.profile.profile_url') AND stop_code IS NULL) OR (status='failed' AND native_author_id IS NULL AND native_material_json IS NULL AND stop_code IS NOT NULL AND length(stop_code) BETWEEN 1 AND 128)) );
CREATE TABLE email_attachments ( id TEXT PRIMARY KEY, email_id TEXT NOT NULL REFERENCES emails(id) ON DELETE CASCADE, provider_attachment_id TEXT NOT NULL, filename TEXT NOT NULL, content_type TEXT NOT NULL, content_id TEXT, content_disposition TEXT, size_bytes INTEGER, direction TEXT NOT NULL CHECK(direction IN ('inbound','outbound')), available INTEGER NOT NULL CHECK(available IN (0,1)), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(email_id, provider_attachment_id) );
CREATE TABLE email_auth_connections ( id TEXT PRIMARY KEY, provider_kind TEXT NOT NULL CHECK(provider_kind IN ('resend','smtp','imap','remote')), secret_record_id TEXT NOT NULL CHECK(length(trim(secret_record_id)) > 0), label TEXT NOT NULL CHECK(length(trim(label)) > 0), available INTEGER NOT NULL CHECK(available IN (0,1)), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(id, provider_kind), UNIQUE(secret_record_id) );
CREATE TABLE email_drafts ( id TEXT PRIMARY KEY, mailbox_ref_id TEXT NOT NULL REFERENCES mailbox_refs(id) ON DELETE RESTRICT, to_address TEXT NOT NULL, creator_id TEXT REFERENCES creators(id) ON DELETE RESTRICT, contact_route_id TEXT REFERENCES creator_contact_routes(id) ON DELETE RESTRICT, reply_to_email_id TEXT REFERENCES emails(id) ON DELETE RESTRICT, subject TEXT NOT NULL, body_text TEXT NOT NULL, body_html TEXT, template_id TEXT REFERENCES email_templates(id) ON DELETE SET NULL, template_variables_json TEXT NOT NULL DEFAULT '{}', state TEXT NOT NULL CHECK(state IN ('draft','trashed')), sending_idempotency_key TEXT, send_reserved_at INTEGER, revision INTEGER NOT NULL CHECK(revision >= 1), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, CHECK((creator_id IS NULL AND contact_route_id IS NULL) OR (creator_id IS NOT NULL AND contact_route_id IS NOT NULL)) );
CREATE TABLE email_provider_identities ( mailbox_ref_id TEXT NOT NULL REFERENCES mailbox_refs(id) ON DELETE RESTRICT, provider_message_id TEXT NOT NULL, email_id TEXT NOT NULL REFERENCES emails(id) ON DELETE CASCADE, direction TEXT NOT NULL CHECK(direction IN ('inbound','outbound')), detail_complete INTEGER NOT NULL CHECK(detail_complete IN (0,1)), updated_at INTEGER NOT NULL, PRIMARY KEY(mailbox_ref_id, provider_message_id) );
CREATE TABLE email_recipients ( email_id TEXT NOT NULL REFERENCES emails(id) ON DELETE RESTRICT, recipient_kind TEXT NOT NULL CHECK(recipient_kind IN ('from','to','cc','bcc','received_for','reply_to')), address TEXT NOT NULL, locator_id TEXT REFERENCES contact_locators(id) ON DELETE RESTRICT, PRIMARY KEY(email_id, recipient_kind, address) );
CREATE TABLE email_templates ( id TEXT PRIMARY KEY, name TEXT NOT NULL, subject_template TEXT NOT NULL, text_template TEXT NOT NULL, html_template TEXT, variables_json TEXT NOT NULL DEFAULT '[]', revision INTEGER NOT NULL CHECK(revision >= 1), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL );
CREATE TABLE email_threads ( id TEXT PRIMARY KEY, mailbox_ref_id TEXT NOT NULL REFERENCES mailbox_refs(id) ON DELETE RESTRICT, creator_id TEXT REFERENCES creators(id) ON DELETE RESTRICT, contact_route_id TEXT REFERENCES creator_contact_routes(id) ON DELETE RESTRICT, provider_thread_key TEXT NOT NULL, subject TEXT NOT NULL, unread_count INTEGER NOT NULL DEFAULT 0, active_folder TEXT NOT NULL CHECK(active_folder IN ('inbox','sent')), archived_at INTEGER, deleted_at INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(mailbox_ref_id, provider_thread_key) );
CREATE TABLE emails ( id TEXT PRIMARY KEY, thread_id TEXT NOT NULL REFERENCES email_threads(id) ON DELETE RESTRICT, provider_message_id TEXT NOT NULL, internet_message_id TEXT, direction TEXT NOT NULL CHECK(direction IN ('inbound','outbound')), subject TEXT NOT NULL, body_text TEXT, body_html TEXT, in_reply_to TEXT, references_json TEXT NOT NULL DEFAULT '[]', delivery_status TEXT NOT NULL, headers_json TEXT NOT NULL DEFAULT '{}', occurred_at INTEGER NOT NULL, origin TEXT NOT NULL CHECK(origin IN ('confirmed_send','provider_import')), UNIQUE(thread_id, provider_message_id) );
CREATE TABLE gmail_bulk_batches ( id TEXT PRIMARY KEY, mailbox_ref_id TEXT NOT NULL REFERENCES mailbox_refs(id), subject TEXT NOT NULL, body TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('draft','running','paused','cancelled','completed')), created_at INTEGER NOT NULL );
CREATE TABLE gmail_bulk_items ( id TEXT PRIMARY KEY, batch_id TEXT NOT NULL REFERENCES gmail_bulk_batches(id), recipient TEXT NOT NULL, source TEXT NOT NULL, fingerprint TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('pending','attempting','accepted','sent','failed','unknown','cancelled')), provider_message_id TEXT, detail TEXT, UNIQUE(batch_id,recipient) );
CREATE TABLE gmail_send_attempts ( idempotency_key TEXT PRIMARY KEY );
CREATE TABLE idempotency_records ( key TEXT PRIMARY KEY, action TEXT NOT NULL, mailbox_ref_id TEXT REFERENCES mailbox_refs(id) ON DELETE RESTRICT, contact_route_id TEXT REFERENCES creator_contact_routes(id) ON DELETE RESTRICT, request_fingerprint TEXT, state TEXT NOT NULL CHECK(state IN ('in_progress','remote_started','remote_accepted','remote_verified','completed','failed')), result_json TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL );
CREATE TABLE identity_conflicts ( id TEXT PRIMARY KEY, conflict_key TEXT NOT NULL UNIQUE, kind TEXT NOT NULL, creator_id TEXT REFERENCES creators(id) ON DELETE RESTRICT, platform_account_id TEXT REFERENCES platform_accounts(id) ON DELETE RESTRICT, locator_id TEXT REFERENCES contact_locators(id) ON DELETE RESTRICT, resolved_target_id TEXT REFERENCES resolved_targets(id) ON DELETE RESTRICT, evidence_json TEXT NOT NULL DEFAULT '{}', state TEXT NOT NULL CHECK(state IN ('open','resolved','dismissed')), created_at INTEGER NOT NULL, resolved_at INTEGER );
CREATE TABLE discovery_evidence_reviews ( id TEXT PRIMARY KEY NOT NULL CHECK(length(id) BETWEEN 1 AND 128), operator_account_id TEXT NOT NULL CHECK(length(trim(operator_account_id)) BETWEEN 1 AND 256), discovery_campaign_id TEXT NOT NULL, criteria_revision INTEGER NOT NULL CHECK(criteria_revision >= 1), search_hit_id TEXT NOT NULL REFERENCES discovery_search_hits(id) ON DELETE CASCADE, candidate_id TEXT NOT NULL REFERENCES discovery_candidates(id) ON DELETE CASCADE, native_author_id TEXT NOT NULL CHECK(length(native_author_id) BETWEEN 1 AND 256), profile_ref TEXT NOT NULL CHECK(length(profile_ref) BETWEEN 1 AND 256), request_id TEXT NOT NULL CHECK(length(trim(request_id)) BETWEEN 1 AND 128), request_hash TEXT NOT NULL CHECK(length(request_hash)=64 AND request_hash NOT GLOB '*[^0-9a-f]*'), material_hash TEXT NOT NULL CHECK(length(material_hash)=64 AND material_hash NOT GLOB '*[^0-9a-f]*'), material_json TEXT NOT NULL CHECK(json_valid(material_json) AND json_type(material_json)='object' AND coalesce(json_extract(material_json,'$.format_version'),0) IN (1,2) AND length(CAST(material_json AS BLOB)) <= 1048576), policy_version TEXT NOT NULL CHECK(length(trim(policy_version)) BETWEEN 1 AND 64), reviewer_json TEXT NOT NULL CHECK(json_valid(reviewer_json) AND json_type(reviewer_json)='object' AND length(CAST(reviewer_json AS BLOB)) <= 2048), findings_json TEXT NOT NULL CHECK(json_valid(findings_json) AND json_type(findings_json)='array' AND length(CAST(findings_json AS BLOB)) <= 65536), verdict TEXT NOT NULL CHECK(verdict IN ('pending','qualified','rejected')), assessment_json TEXT NOT NULL CHECK(json_valid(assessment_json) AND json_type(assessment_json)='object' AND length(CAST(assessment_json AS BLOB)) <= 16384), created_at INTEGER NOT NULL CHECK(created_at >= 0), UNIQUE(operator_account_id, discovery_campaign_id, request_id), FOREIGN KEY(discovery_campaign_id, criteria_revision) REFERENCES discovery_campaign_revisions(discovery_campaign_id, revision) ON DELETE CASCADE );
CREATE TABLE discovery_facebook_content_targets ( search_hit_id TEXT PRIMARY KEY REFERENCES discovery_profile_reads(search_hit_id) ON DELETE CASCADE, discovery_campaign_id TEXT NOT NULL, platform TEXT NOT NULL CHECK(platform='facebook'), profile_ref TEXT NOT NULL, author_id TEXT NOT NULL CHECK(length(author_id) BETWEEN 1 AND 20 AND author_id NOT GLOB '*[^0-9]*' AND substr(author_id,1,1)!='0'), profile_url TEXT NOT NULL CHECK(profile_url='https://www.facebook.com/profile.php?id=' || author_id), expected_revision INTEGER NOT NULL CHECK(expected_revision >= 1), call_number INTEGER NOT NULL CHECK(call_number > 0), status TEXT NOT NULL CHECK(status IN ('reading','completed','failed')), source_urls_json TEXT CHECK(source_urls_json IS NULL OR (json_valid(source_urls_json) AND json_type(source_urls_json)='array' AND json_array_length(source_urls_json) BETWEEN 1 AND 3 AND length(CAST(source_urls_json AS BLOB)) <= 1024)), stop_code TEXT, updated_at INTEGER NOT NULL CHECK(updated_at >= 0), FOREIGN KEY(discovery_campaign_id, platform, profile_ref) REFERENCES discovery_platform_runs(discovery_campaign_id, platform, profile_ref) ON DELETE CASCADE, FOREIGN KEY(discovery_campaign_id, expected_revision) REFERENCES discovery_campaign_revisions(discovery_campaign_id, revision) ON DELETE CASCADE, CHECK((status='reading' AND source_urls_json IS NULL AND stop_code IS NULL) OR (status='completed' AND source_urls_json IS NOT NULL AND stop_code IS NULL) OR (status='failed' AND source_urls_json IS NULL AND stop_code IS NOT NULL)) );
CREATE TABLE discovery_facebook_identity_reads ( search_hit_id TEXT PRIMARY KEY REFERENCES discovery_search_hits(id), discovery_campaign_id TEXT NOT NULL REFERENCES discovery_campaigns(id), platform TEXT NOT NULL CHECK(platform='facebook'), profile_ref TEXT NOT NULL CHECK(length(profile_ref)>0), source_url TEXT NOT NULL CHECK(source_url LIKE 'https://www.facebook.com/%'), expected_revision INTEGER NOT NULL CHECK(expected_revision>0), call_number INTEGER NOT NULL CHECK(call_number BETWEEN 1 AND 4294967295), status TEXT NOT NULL CHECK(status IN ('reading','completed','failed')), native_identity_json TEXT, stop_code TEXT, updated_at INTEGER NOT NULL, FOREIGN KEY(discovery_campaign_id,expected_revision) REFERENCES discovery_campaign_revisions(discovery_campaign_id,revision), CHECK((status='reading' AND native_identity_json IS NULL AND stop_code IS NULL) OR (status='failed' AND native_identity_json IS NULL AND stop_code IS NOT NULL AND length(stop_code)>0) OR (status='completed' AND stop_code IS NULL AND native_identity_json IS NOT NULL AND json_valid(native_identity_json) AND json_type(native_identity_json)='object' AND length(CAST(native_identity_json AS BLOB))<=4000 AND json_extract(native_identity_json,'$.adapter_version') IS '1.0.0' AND json_extract(native_identity_json,'$.source_url') IS source_url AND json_extract(native_identity_json,'$.evidence_source') IS 'native_profile_header_response' AND json_type(native_identity_json,'$.id') IS 'text' AND length(json_extract(native_identity_json,'$.id')) BETWEEN 1 AND 20 AND substr(json_extract(native_identity_json,'$.id'),1,1)!='0' AND json_extract(native_identity_json,'$.id') NOT GLOB '*[^0-9]*')) );
CREATE TABLE discovery_facebook_original_attempts ( search_hit_id TEXT NOT NULL REFERENCES discovery_facebook_content_targets(search_hit_id), discovery_campaign_id TEXT NOT NULL REFERENCES discovery_campaigns(id), profile_ref TEXT NOT NULL, author_id TEXT NOT NULL, source_url TEXT NOT NULL, expected_revision INTEGER NOT NULL CHECK(expected_revision>0), call_number INTEGER NOT NULL CHECK(call_number>0), status TEXT NOT NULL CHECK(status IN ('reading','completed','failed')), native_content_json TEXT CHECK(native_content_json IS NULL OR (json_valid(native_content_json) AND json_type(native_content_json)='object' AND length(CAST(native_content_json AS BLOB))<=16000)), stop_code TEXT, updated_at INTEGER NOT NULL, PRIMARY KEY(search_hit_id,source_url), FOREIGN KEY(discovery_campaign_id,expected_revision) REFERENCES discovery_campaign_revisions(discovery_campaign_id,revision), CHECK((status='reading' AND native_content_json IS NULL AND stop_code IS NULL) OR(status='completed' AND native_content_json IS NOT NULL AND stop_code IS NULL) OR(status='failed' AND native_content_json IS NULL AND stop_code IS NOT NULL)));
CREATE TABLE discovery_identity_reads ( search_hit_id TEXT PRIMARY KEY REFERENCES discovery_search_authors(search_hit_id) ON DELETE CASCADE, discovery_campaign_id TEXT NOT NULL REFERENCES discovery_campaigns(id) ON DELETE CASCADE, platform TEXT NOT NULL CHECK(platform='twitter'), profile_ref TEXT NOT NULL, author_handle TEXT NOT NULL, source_url TEXT NOT NULL, post_id TEXT NOT NULL, expected_revision INTEGER NOT NULL CHECK(expected_revision >= 1), call_number INTEGER NOT NULL CHECK(call_number > 0), status TEXT NOT NULL CHECK(status IN ('reading','completed','failed')), account_id TEXT, observed_source_url TEXT, stop_code TEXT, updated_at INTEGER NOT NULL, FOREIGN KEY(discovery_campaign_id, platform, profile_ref) REFERENCES discovery_platform_runs(discovery_campaign_id, platform, profile_ref) ON DELETE CASCADE, CHECK((status='reading' AND account_id IS NULL AND observed_source_url IS NULL AND stop_code IS NULL) OR (status='completed' AND account_id IS NOT NULL AND observed_source_url IS NOT NULL AND stop_code IS NULL) OR (status='failed' AND account_id IS NULL AND observed_source_url IS NULL AND stop_code IS NOT NULL)) );
